import{c as s,Q as a,j as o,m as t}from"./chunks/framework.W-g_WCNV.js";const h=JSON.parse('{"title":"Passkeys","description":"Set up and use passkeys (WebAuthn) for passwordless, phishing-resistant login.","frontmatter":{"title":"Passkeys","description":"Set up and use passkeys (WebAuthn) for passwordless, phishing-resistant login."},"headers":[],"relativePath":"auth/passkeys.md","filePath":"auth/passkeys.md"}'),i={name:"auth/passkeys.md"};function r(n,e,d,p,l,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<p>A passkey is a cryptographic key stored on your device - your laptop, phone, or a hardware security key. Instead of typing a password and waiting for a code, you authenticate using your device&#39;s built-in method: fingerprint, face recognition, or PIN.</p><p>Passkeys implement the WebAuthn standard (also called FIDO2). They are phishing-resistant because the key is bound to the specific website it was created for. A passkey created for <code>auth.example.com</code> will never work on <code>auth-example.com</code>.</p><h2 id="registering-a-passkey" tabindex="-1">Registering a passkey <a class="header-anchor" href="#registering-a-passkey" aria-label="Permalink to &quot;Registering a passkey&quot;">​</a></h2><p>You must be logged in to register a passkey (use password + OTP for your first login).</p><ol><li>Go to <code>/register/passkey</code>.</li><li>Give the passkey a name so you can identify it later (for example, &quot;MacBook&quot; or &quot;iPhone&quot;).</li><li>Click <strong>Register passkey</strong>. Your browser will ask you to use your fingerprint, face, or device PIN.</li><li>Done.</li></ol><p>You can register multiple passkeys - one per device is typical.</p><h2 id="logging-in-with-a-passkey" tabindex="-1">Logging in with a passkey <a class="header-anchor" href="#logging-in-with-a-passkey" aria-label="Permalink to &quot;Logging in with a passkey&quot;">​</a></h2><p>Go to <code>/login/passkey</code> and click <strong>Use passkey</strong>. Your browser will prompt you to choose a passkey and authenticate with your device.</p><p>Passkey login counts as both factors - you do not need to complete OTP or TOTP after a successful passkey authentication.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>Passkeys require JavaScript. The login and registration pages load a small JavaScript file (<code>/static/js/passkey.js</code>) to handle the WebAuthn API calls. No external scripts are loaded.</p><p>Your browser must support WebAuthn. All modern browsers (Chrome, Firefox, Safari, Edge) and most recent mobile browsers support it.</p><h2 id="multiple-passkeys" tabindex="-1">Multiple passkeys <a class="header-anchor" href="#multiple-passkeys" aria-label="Permalink to &quot;Multiple passkeys&quot;">​</a></h2><p>You can register as many passkeys as you want. This is encouraged - register one on each device you regularly use. If one device is lost, the others still work.</p><p>Admins can see which passkeys are registered for a user at <code>/users/:id</code>. Individual passkeys can also be revoked from there.</p><h2 id="admin-on-a-subdomain" tabindex="-1">Admin on a subdomain <a class="header-anchor" href="#admin-on-a-subdomain" aria-label="Permalink to &quot;Admin on a subdomain&quot;">​</a></h2><p>Passkeys are bound to the host in <code>BASE_URL</code>. When the admin panel runs on its own subdomain (for example <code>admin.auth.example.com</code> while <code>BASE_URL</code> is <code>https://auth.example.com</code>), set the <code>ADMIN_URL</code> environment variable to that admin address. GateKeeper adds it to the list of allowed passkey origins so admin passkeys register and sign in correctly.</p><p>The admin subdomain must sit under the same registrable domain as <code>BASE_URL</code> (both under <code>example.com</code> in the example above). Passkeys cannot be shared across entirely separate domains, such as <code>.app</code> and <code>.live</code>.</p>',18)])])}const m=s(i,[["render",r]]);export{h as __pageData,m as default};
